-- DOCUMENTATION ONLY. PostgreSQL 16. Never execute from this project.
-- ids are generated by the application (no DB defaults).

CREATE TABLE patients (
  clinic_id              uuid NOT NULL REFERENCES clinics (id),
  id                     uuid NOT NULL,
  file_number            text NOT NULL,
  full_name              text NOT NULL,
  phone                  text NOT NULL,
  birth_date             date NOT NULL,
  gender                 text NOT NULL CHECK (gender IN ('male','female')),
  registration_branch_id uuid NOT NULL,
  civil_id               text NULL,
  status                 text NOT NULL CHECK (status IN ('active','archived')),
  created_at             timestamptz NOT NULL,
  updated_at             timestamptz NOT NULL,
  PRIMARY KEY (clinic_id, id),
  UNIQUE (clinic_id, file_number),
  UNIQUE (clinic_id, phone),
  FOREIGN KEY (clinic_id, registration_branch_id) REFERENCES branches (clinic_id, id)
);
CREATE INDEX patients_clinic_name_idx ON patients (clinic_id, full_name);
CREATE INDEX patients_clinic_branch_status_idx ON patients (clinic_id, registration_branch_id, status);
CREATE INDEX patients_clinic_civil_id_idx ON patients (clinic_id, civil_id);

ALTER TABLE patients ENABLE ROW LEVEL SECURITY;
ALTER TABLE patients FORCE ROW LEVEL SECURITY;
CREATE POLICY patients_tenant_isolation ON patients
  USING (clinic_id = current_setting('app.clinic_id')::uuid)
  WITH CHECK (clinic_id = current_setting('app.clinic_id')::uuid);
